css:
/* ══════════════════════════════════════════════════════════
   山野之间 · Between the Wild
   母体：Writer's Atelier（暖燕麦纸底 / 纸白卡片 / 1px 出版栏线 / 宋体长文）
   有意偏离：强调色由母体琥珀 #E08A3C 改为苔绿 #4A6142（客体为苔与纸），
             暖琥珀只保留在标本纸的光晕里，不参与 UI 焦点。
   ══════════════════════════════════════════════════════════ */

:root {
  --paper:        #EAE6DF;   /* 暖燕麦全屏纸底 */
  --paper-deep:   #E2DDD4;   /* 次级块底 */
  --card:         #FCFBF8;   /* 卡片底（避开刺眼死白 #FFF） */

  --ink:          #1F1E1C;   /* 炭墨主字 */
  --ink-2:        #4A463F;   /* 次级文字 */
  --ink-3:        #6E6960;   /* 三级线索（已按 AA 对比度校过） */

  --moss:         #4A6142;   /* 唯一的强调色 · 苔绿 */
  --moss-deep:    #33462E;
  --moss-tint:    #E7EBE1;

  --line:         1px solid rgba(31, 30, 28, 0.13);
  --line-soft:    1px solid rgba(31, 30, 28, 0.08);
  --line-moss:    1px solid rgba(74, 97, 66, 0.34);

  /* 标本纸随时刻变化的六支变量 */
  --spec-ground:  #E7EADA;
  --spec-halo:    #F1F3E6;
  --spec-line:    rgba(74, 97, 66, 0.20);
  --spec-leaf-a:  #566E4D;
  --spec-leaf-b:  #3B5942;
  --spec-leaf-c:  #6B7C50;
  --spec-ink:     #404B3A;

  --r-card: 8px;
  --r-tag: 4px;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);

  --sans: "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", system-ui, sans-serif;
  --serif: "Songti SC", "Noto Serif SC", "Source Han Serif SC", STSong, Georgia, serif;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
}

/* 时刻：午 —— 光更直更亮，叶色偏黄 */
[data-moment="noon"] {
  --spec-ground: #EDEEE0;
  --spec-halo:   #F7F8EC;
  --spec-line:   rgba(74, 97, 66, 0.16);
  --spec-leaf-a: #6C7D4E;
  --spec-leaf-b: #54663F;
  --spec-leaf-c: #88954F;
  --spec-ink:    #3E4A34;
}
/* 时刻：暮 —— 低角暖光，叶色深而冷 */
[data-moment="dusk"] {
  --spec-ground: #E4E0D8;
  --spec-halo:   #EDE9DC;
  --spec-line:   rgba(60, 74, 60, 0.24);
  --spec-leaf-a: #3F5340;
  --spec-leaf-b: #2E4234;
  --spec-leaf-c: #55613C;
  --spec-ink:    #333A31;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, p, dl, dd, dt, ol, li, figure, form { margin: 0; padding: 0; }
ol { list-style: none; }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; color: inherit; }
button { cursor: pointer; }

:focus-visible {
  outline: 2px solid var(--moss-deep);
  outline-offset: 3px;
  border-radius: 2px;
}
::selection { background: #D6DFC0; color: var(--moss-deep); }

.skip {
  position: absolute;
  left: 16px; top: 12px;
  z-index: 40;
  padding: 10px 16px;
  background: var(--moss-deep);
  color: #F3F2EC;
  font-size: 13px;
  border-radius: var(--r-tag);
  transform: translateY(-160%);
  transition: transform 0.2s var(--ease);
}
.skip:focus { transform: translateY(0); }

/* ── 通用排版原子 ───────────────────────────────── */

.eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--ink-3);
  line-height: 1.5;
}
.eyebrow--light { color: #B9C6AE; }

.h2 {
  font-family: var(--serif);
  font-weight: 400;
  font-size: 38px;
  line-height: 1.28;
  letter-spacing: 0.01em;
  color: var(--ink);
}
.h2--flow { font-size: 34px; }
.h2--light { color: #F1F0EA; }

.dot {
  display: inline-block;
  width: 3px; height: 3px;
  margin: 0 10px;
  vertical-align: 3px;
  background: var(--ink-3);
  border-radius: 50%;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 22px;
  border-radius: var(--r-tag);
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: transform 0.18s var(--ease), background-color 0.18s var(--ease),
              border-color 0.18s var(--ease), color 0.18s var(--ease);
}
.btn--primary { background: var(--moss); color: #F4F5EF; }
.btn--primary:hover { background: var(--moss-deep); }
.btn--primary:active { transform: scale(0.98); }
.btn--primary[disabled] { background: #9DA795; color: #EFEFE9; cursor: not-allowed; transform: none; }

.btn--ghost {
  background: transparent;
  border-color: rgba(31, 30, 28, 0.24);
  color: var(--ink-2);
}
.btn--ghost:hover { border-color: var(--ink); color: var(--ink); }

.arrow-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--moss);
  font-size: 14px;
  font-weight: 600;
  color: var(--moss-deep);
  transition: gap 0.22s var(--ease), color 0.18s var(--ease);
}
.arrow-link:hover { gap: 16px; color: var(--ink); }

/* ── 顶栏 ───────────────────────────────────────── */
.masthead {
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(234, 230, 223, 0.9);
  backdrop-filter: blur(10px);
  border-bottom: var(--line);
}
.masthead__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  max-width: 1280px;
  margin: 0 auto;
  padding: 14px 40px;
}
.brand { display: flex; flex-direction: column; gap: 2px; }
.brand__zh {
  font-family: var(--serif);
  font-size: 21px;
  letter-spacing: 0.16em;
  line-height: 1.2;
}
.brand__en {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.nav { display: flex; align-items: center; gap: 28px; }
.nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 14px;
  color: var(--ink-2);
  transition: color 0.18s var(--ease);
}
.nav a::after {
  content: "";
  position: absolute;
  left: 0; right: 100%; bottom: 10px;
  height: 1px;
  background: var(--moss);
  transition: right 0.22s var(--ease);
}
.nav a:hover { color: var(--ink); }
.nav a:hover::after { right: 0; }
.nav__cta { color: var(--moss-deep) !important; font-weight: 600; }

/* ── 01 首屏 ────────────────────────────────────── */
.hero {
  display: grid;
  grid-template-columns: 5fr 7fr;
  gap: 56px;
  max-width: 1280px;
  margin: 0 auto;
  padding: 56px 40px 72px;
  align-items: start;
}
.hero__copy { padding-top: 20px; }

.hero__title {
  font-family: var(--serif);
  font-weight: 400;
  font-size: 58px;
  line-height: 1.22;
  letter-spacing: 0.012em;
  margin: 26px 0 24px;
}
.hero__lede {
  font-family: var(--serif);
  font-size: 17px;
  line-height: 1.85;
  color: var(--ink-2);
  max-width: 32em;
}

.moment {
  margin: 36px 0 34px;
  padding: 20px 0 22px;
  border-top: var(--line-soft);
  border-bottom: var(--line-soft);
}
.moment__label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--ink-3);
  margin-bottom: 14px;
}
.moment__switch { display: flex; gap: 8px; flex-wrap: wrap; }
.moment__btn {
  min-height: 44px;
  padding: 0 16px;
  background: transparent;
  border: 1px solid rgba(31, 30, 28, 0.18);
  border-radius: var(--r-tag);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
  transition: background-color 0.2s var(--ease), border-color 0.2s var(--ease), color 0.2s var(--ease);
}
.moment__btn:hover { border-color: var(--moss); color: var(--ink); }
.moment__btn.is-active {
  background: var(--moss-tint);
  border-color: var(--moss);
  color: var(--moss-deep);
  font-weight: 600;
}
.moment__readout {
  margin-top: 14px;
  font-size: 13px;
  color: var(--ink-3);
  min-height: 1.7em;
  transition: opacity 0.24s var(--ease);
}
.moment__readout.is-swapping { opacity: 0; }

/* 标本纸 */
.specimen { position: relative; }
.specimen__paper {
  border: var(--line);
  border-radius: var(--r-card);
  background: var(--spec-ground);
  overflow: hidden;
  box-shadow: 0 1px 3px rgba(31, 30, 28, 0.04);
}
.specimen__svg {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 520 / 660;
  transition: background-color 0.5s var(--ease);
}
.specimen__svg .ground { fill: var(--spec-ground); transition: fill 0.5s var(--ease); }
.specimen__svg .rules path { fill: none; stroke: var(--spec-line); stroke-width: 1; transition: stroke 0.5s var(--ease); }
.specimen__svg .halo circle { fill: var(--spec-halo); transition: fill 0.5s var(--ease); }

.specimen__svg .stem { fill: none; stroke: var(--spec-ink); stroke-width: 2.6; stroke-linecap: round; transition: stroke 0.5s var(--ease); }
.specimen__svg .bud { fill: var(--spec-ink); transition: fill 0.5s var(--ease); }
.specimen__svg .petiole { fill: none; stroke: var(--spec-ink); stroke-width: 1.9; stroke-linecap: round; transition: stroke 0.5s var(--ease); }
.specimen__svg .lamina { transition: fill 0.5s var(--ease); }
.specimen__svg .vein { fill: none; stroke: var(--spec-leaf-c); stroke-width: 1.2; opacity: 0.5; transition: stroke 0.5s var(--ease); }

.specimen__svg .leaf--1 .lamina, .specimen__svg .leaf--5 .lamina, .specimen__svg .leaf--7 .lamina { fill: var(--spec-leaf-a); }
.specimen__svg .leaf--2 .lamina, .specimen__svg .leaf--6 .lamina { fill: var(--spec-leaf-b); }
.specimen__svg .leaf--3 .lamina, .specimen__svg .leaf--4 .lamina { fill: var(--spec-leaf-c); }

.specimen__svg .label__rule { fill: none; stroke: var(--spec-ink); stroke-width: 1; opacity: 0.5; transition: stroke 0.5s var(--ease); }
.specimen__svg .label__latin {
  font-family: Georgia, "Songti SC", serif;
  font-style: italic;
  font-size: 20px;
  fill: var(--spec-ink);
  transition: fill 0.5s var(--ease);
}
.specimen__svg .label__meta {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.05em;
  fill: var(--spec-ink);
  opacity: 0.85;
  transition: fill 0.5s var(--ease);
}
.specimen__svg .scale path {
  fill: none;
  stroke: var(--spec-ink);
  stroke-width: 1;
  opacity: 0.55;
  transition: stroke 0.5s var(--ease);
}
.specimen__svg .scale__text {
  fill: var(--spec-ink);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  opacity: 0.75;
  transition: fill 0.5s var(--ease);
}

.specimen__caption {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 14px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: var(--line-soft);
}
.specimen__caption-main { font-size: 13px; font-weight: 600; letter-spacing: 0.04em; }
.specimen__caption-sub { font-size: 12px; color: var(--ink-3); }

/* ── 02 品牌故事 ────────────────────────────────── */
.story {
  background: var(--paper-deep);
  border-top: var(--line);
  border-bottom: var(--line);
  padding: 80px 40px 88px;
}
.story__eyebrow,
.story__grid {
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}
.story__grid {
  display: grid;
  grid-template-columns: 4fr 7fr;
  gap: 64px;
  margin-top: 28px;
}
.story__aside .h2 { margin-bottom: 32px; }

.ledger { border-top: var(--line-soft); }
.ledger__row {
  display: grid;
  grid-template-columns: 6.5em 1fr;
  gap: 12px;
  padding: 12px 0;
  border-bottom: var(--line-soft);
}
.ledger dt { font-size: 12px; letter-spacing: 0.08em; color: var(--ink-3); }
.ledger dd { font-size: 14px; color: var(--ink-2); }

.story__body { padding-top: 6px; }
.story__lead {
  font-family: var(--serif);
  font-size: 22px;
  line-height: 1.65;
  color: var(--ink);
  margin-bottom: 26px;
  max-width: 30em;
}
.story__body p {
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1.92;
  color: var(--ink-2);
  max-width: 34em;
  margin-bottom: 20px;
}
.story__close {
  margin-top: 30px !important;
  padding-top: 22px;
  border-top: var(--line-soft);
  color: var(--ink) !important;
}

/* ── 通用区块头 ─────────────────────────────────── */
.section-head {
  display: grid;
  grid-template-columns: 4fr 7fr;
  gap: 64px;
  align-items: end;
  max-width: 1200px;
  margin: 0 auto 40px;
  padding-bottom: 22px;
  border-bottom: var(--line);
}
.section-head .eyebrow { margin-bottom: 14px; }
.section-head__note {
  font-size: 14px;
  line-height: 1.8;
  color: var(--ink-3);
  max-width: 30em;
}

/* ── 03 自然历 ──────────────────────────────────── */
.almanac {
  max-width: 1280px;
  margin: 0 auto;
  padding: 80px 40px 88px;
}
.almanac__list { max-width: 1200px; margin: 0 auto; border-top: var(--line-soft); }

.entry {
  display: grid;
  grid-template-columns: 6.5em 9.5em 1.5fr 1.1fr 5.5em;
  gap: 20px;
  align-items: baseline;
  padding: 20px 0;
  border-bottom: var(--line-soft);
  transition: background-color 0.22s var(--ease);
}
.entry[hidden] { display: none; }
.entry:hover { background: rgba(252, 251, 248, 0.6); }

/* 错位缩进：条目越往下越内收，形成"翻页"节奏 */
.entry:nth-child(2),
.entry:nth-child(5) { padding-left: 24px; }
.entry:nth-child(3),
.entry:nth-child(6) { padding-left: 48px; }

.entry__no { font-family: var(--mono); font-size: 12px; color: var(--ink-3); letter-spacing: 0.04em; }
.entry__when { font-size: 13px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
.entry__what strong { display: block; font-family: var(--serif); font-size: 19px; font-weight: 400; line-height: 1.4; }
.entry__what em { font-size: 12px; font-style: normal; color: var(--ink-3); letter-spacing: 0.04em; }
.entry__where { font-size: 13px; color: var(--ink-2); }
.entry__flag {
  justify-self: end;
  align-self: center;
  padding: 3px 10px;
  border: var(--line-moss);
  border-radius: 999px;
  background: var(--moss-tint);
  color: var(--moss-deep);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.entry__flag--muted {
  background: transparent;
  border-color: rgba(31, 30, 28, 0.14);
  color: var(--ink-3);
  font-weight: 400;
}
.entry.is-current .entry__no { color: var(--moss-deep); font-weight: 600; }
.entry.is-current .entry__what strong { color: var(--moss-deep); }

.filter {
  max-width: 1200px;
  margin: 28px auto 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.filter__label { font-size: 13px; color: var(--ink-3); margin-right: 10px; }
.chip {
  min-height: 44px;
  padding: 0 18px;
  background: transparent;
  border: 1px solid rgba(31, 30, 28, 0.16);
  border-radius: 999px;
  font-size: 13px;
  color: var(--ink-2);
  transition: background-color 0.2s var(--ease), border-color 0.2s var(--ease), color 0.2s var(--ease);
}
.chip:hover { border-color: var(--moss); color: var(--ink); }
.chip.is-active { background: var(--moss); border-color: var(--moss); color: #F4F5EF; font-weight: 600; }

.almanac__empty {
  max-width: 1200px;
  margin: 28px auto 0;
  padding: 28px 26px;
  background: var(--card);
  border: var(--line);
  border-radius: var(--r-card);
}
.almanac__empty[hidden] { display: none; }
.almanac__empty-title { font-family: var(--serif); font-size: 20px; margin-bottom: 8px; }
.almanac__empty-text { font-size: 14px; color: var(--ink-2); margin-bottom: 18px; }

/* ── 04 器物档案 ────────────────────────────────── */
.archive {
  background: var(--paper-deep);
  border-top: var(--line);
  border-bottom: var(--line);
  padding: 80px 40px 76px;
}
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
  align-items: start;
}
/* 中间一列下沉，打破等宽三分的呆板 */
.cards .card:nth-child(2) { margin-top: 40px; }

.card {
  background: var(--card);
  border: var(--line);
  border-radius: var(--r-card);
  padding: 26px 24px 22px;
  box-shadow: 0 1px 3px rgba(31, 30, 28, 0.03);
  transition: border-color 0.22s var(--ease), transform 0.22s var(--ease);
}
.card:hover { border-color: rgba(74, 97, 66, 0.4); transform: translateY(-2px); }
.card.is-open { border-color: var(--moss); }

.card__no {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--ink-3);
  margin-bottom: 14px;
}
.card__title {
  font-family: var(--serif);
  font-weight: 400;
  font-size: 23px;
  line-height: 1.35;
  margin-bottom: 6px;
}
.card__latin { font-size: 12px; letter-spacing: 0.05em; color: var(--ink-3); margin-bottom: 16px; }
.card__note {
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.85;
  color: var(--ink-2);
  padding-bottom: 18px;
  border-bottom: var(--line-soft);
}

.card__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 44px;
  margin-top: 6px;
  padding: 0;
  background: transparent;
  border: 0;
  text-align: left;
  color: var(--moss-deep);
  font-size: 14px;
  font-weight: 600;
}
.card__toggle:hover { color: var(--ink); }
.card__toggle-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px; height: 24px;
  flex: 0 0 24px;
  border: var(--line-moss);
  border-radius: 50%;
  font-size: 13px;
  line-height: 1;
  background: var(--moss-tint);
  transition: transform 0.24s var(--ease);
}
.card.is-open .card__toggle-mark { transform: rotate(45deg); }

.card__detail[hidden] { display: none; }
.card__detail.is-entering { animation: push-in 0.34s var(--ease) both; }
@keyframes push-in {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.dossier { margin-top: 14px; padding-top: 14px; border-top: var(--line-soft); }
.dossier > div {
  display: grid;
  grid-template-columns: 4.5em 1fr;
  gap: 10px;
  padding: 7px 0;
}
.dossier dt { font-size: 12px; color: var(--ink-3); letter-spacing: 0.06em; }
.dossier dd { font-size: 13px; color: var(--ink-2); line-height: 1.6; }
.dossier__hand {
  margin-top: 12px;
  padding: 12px 14px;
  background: var(--moss-tint);
  border: var(--line-moss);
  border-radius: var(--r-tag);
  font-family: var(--serif);
  font-size: 14px;
  line-height: 1.8;
  color: var(--moss-deep);
}

.archive__foot {
  max-width: 1200px;
  margin: 40px auto 0;
  padding-top: 20px;
  border-top: var(--line-soft);
  font-size: 12px;
  line-height: 1.9;
  color: var(--ink-3);
}

/* ── 05 季候信 ──────────────────────────────────── */
.letter {
  background: var(--moss-deep);
  color: #F1F0EA;
  padding: 84px 40px 88px;
}
.letter__grid {
  display: grid;
  grid-template-columns: 6fr 5fr;
  gap: 64px;
  max-width: 1200px;
  margin: 0 auto;
  align-items: start;
}
.letter__copy .eyebrow { margin-bottom: 22px; }
.letter__lede {
  margin-top: 24px;
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1.9;
  color: #C9D2BF;
  max-width: 30em;
}

.signup {
  padding: 28px 26px 26px;
  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--r-card);
}
.signup__row { margin-bottom: 18px; }
.signup__row[hidden] { display: none; }
.signup__label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: #DCE3D3;
  margin-bottom: 10px;
}
.signup__input {
  width: 100%;
  min-height: 48px;
  padding: 0 14px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: var(--r-tag);
  color: #F7F6F1;
  font-family: var(--sans);
  font-size: 15px;
  transition: border-color 0.2s var(--ease), background-color 0.2s var(--ease);
}
.signup__input::placeholder { color: #9BA893; }
.signup__input:hover { border-color: rgba(255, 255, 255, 0.4); }
.signup__input:focus-visible {
  outline: 2px solid #C6D6B7;
  outline-offset: 2px;
  border-color: #C6D6B7;
  background: rgba(255, 255, 255, 0.11);
}
.signup__input[aria-invalid="true"] { border-color: #E0A899; background: rgba(224, 168, 153, 0.1); }
.signup__hint { margin-top: 10px; font-size: 12.5px; color: #A9B6A0; }

.signup__error {
  margin-bottom: 16px;
  padding: 12px 14px;
  background: rgba(224, 168, 153, 0.12);
  border: 1px solid rgba(224, 168, 153, 0.44);
  border-radius: var(--r-tag);
  color: #F3D9D0;
  font-size: 13px;
  line-height: 1.7;
}
.signup__error[hidden] { display: none; }
.signup__error a { text-decoration: underline; text-underline-offset: 3px; }

.signup .btn--primary { width: 100%; }
.signup .btn--primary[disabled] { background: rgba(255, 255, 255, 0.16); color: #C3CBB9; }

.signup__done[hidden] { display: none; }
.signup__done-title { font-family: var(--serif); font-size: 19px; color: #EAF0E2; margin-bottom: 8px; }
.signup__done-title span { color: #A9C08F; }
.signup__done-text { font-size: 13.5px; line-height: 1.75; color: #BCC6B2; margin-bottom: 18px; }
.signup .btn--ghost { border-color: rgba(255, 255, 255, 0.3); color: #E4E9DC; }
.signup .btn--ghost:hover { border-color: #E4E9DC; color: #FFFFFF; }

/* ── 页脚 ───────────────────────────────────────── */
.colophon { background: var(--paper); padding: 40px 40px 48px; }
.colophon__grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 48px;
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 26px;
  border-top: var(--line);
}
.colophon__brand { font-family: var(--serif); font-size: 16px; letter-spacing: 0.06em; margin-bottom: 10px; }
.colophon__desc { font-size: 12.5px; line-height: 1.85; color: var(--ink-3); max-width: 46em; }
.colophon__meta { font-size: 12px; color: var(--ink-3); line-height: 1.9; letter-spacing: 0.03em; }
.colophon__top {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  margin-top: 6px;
  font-size: 13px;
  color: var(--moss-deep);
  border-bottom: 1px solid var(--moss);
}

/* ══ 响应式 ═══════════════════════════════════════ */

