  .hero { padding: 32px 20px 48px; gap: 32px; }
  .hero__title { font-size: 34px; line-height: 1.3; margin: 20px 0; }
  .hero__lede { font-size: 16px; }
  .specimen { max-width: 100%; }
  .moment { margin: 28px 0 26px; }
  .moment__btn { flex: 1 1 auto; padding: 0 12px; }

  .story, .archive, .letter { padding: 52px 20px 56px; }
  .almanac { padding: 52px 20px 56px; }
  .story__grid, .section-head, .letter__grid { gap: 26px; }
  .h2 { font-size: 28px; }
  .h2--flow { font-size: 26px; }
  .story__lead { font-size: 19px; }
  .story__body p, .letter__lede { font-size: 16px; }
  .ledger__row { grid-template-columns: 5.5em 1fr; }

  /* 自然历：单列纵向流，取消错位缩进 */
  .entry {
    grid-template-columns: 1fr auto;
    grid-template-areas:
      "no flag"
      "when flag"
      "what flag"
      "where flag";
    gap: 4px 14px;
