  }
  .entry:nth-child(2), .entry:nth-child(3),
  .entry:nth-child(4), .entry:nth-child(5), .entry:nth-child(6) { padding-left: 0; }
  .entry__no { grid-area: no; }
  .entry__when { grid-area: when; }
  .entry__what { grid-area: what; margin-top: 4px; }
  .entry__where { grid-area: where; }
  .entry__flag { grid-area: flag; align-self: start; }

  .filter__label { width: 100%; margin: 0 0 2px; }
  .chip { flex: 1 1 auto; padding: 0 14px; }

  .cards { grid-template-columns: 1fr; gap: 16px; }
  .card { padding: 22px 20px 18px; }
  .card__title { font-size: 21px; }

  .signup { padding: 24px 20px 22px; }

  .colophon { padding: 32px 20px 40px; }
  .colophon__grid { grid-template-columns: 1fr; gap: 26px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
