/* 山野之间 · 交互
   - 时刻切换（晨/午/暮）：驱动标本纸与图注
   - 自然历季节筛选 + 空状态
   - 器物档案原位展开（无弹窗、无跳页）
   - 季候信订阅：校验 / 禁用 / 成功 / 回落
   所有过渡只驱动 transform、opacity 与颜色，不改动布局属性。 */

(function () {
  'use strict';

  var root = document.documentElement;
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ── 01 时刻切换 ─────────────────────────────── */

  var MOMENTS = {
    dawn: {
      readout: '露水未退，叶脉在斜光里最先醒来。',
      caption: '标本 NO. 01 · 橄榄',
      sub: '纸白卡纸 · 干压定型 · 采集于春末清晨'
    },
    noon: {
      readout: '正午的光把叶面照得薄而透，影子收成短短一截。',
      caption: '标本 NO. 01 · 橄榄（正午光）',
      sub: '纸白卡纸 · 压平八周 · 叶绿素尚未褪尽'
    },
    dusk: {
      readout: '太阳压低之后，叶背的灰绿反而更清楚。',
      caption: '标本 NO. 01 · 橄榄（暮光）',
      sub: '纸白卡纸 · 干压定型 · 采收于日落前'
    }
  };

  var momentBtns = Array.prototype.slice.call(document.querySelectorAll('.moment__btn'));
  var readout = document.getElementById('moment-readout');
  var capMain = document.getElementById('specimen-caption');
  var capSub = document.getElementById('specimen-caption-sub');

  function setMoment(key) {
    var data = MOMENTS[key];
    if (!data) { return; }

    root.setAttribute('data-moment', key);

    momentBtns.forEach(function (btn) {
      var on = btn.getAttribute('data-moment') === key;
      btn.classList.toggle('is-active', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    });

    if (reduce) {
      readout.textContent = data.readout;
      capMain.textContent = data.caption;
      capSub.textContent = data.sub;
      return;
    }

    readout.classList.add('is-swapping');
    window.setTimeout(function () {
      readout.textContent = data.readout;
      capMain.textContent = data.caption;
      capSub.textContent = data.sub;
      readout.classList.remove('is-swapping');
    }, 180);
  }

  momentBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setMoment(btn.getAttribute('data-moment'));
    });
  });

  /* ── 02 自然历筛选 ───────────────────────────── */

  var entries = Array.prototype.slice.call(document.querySelectorAll('.entry'));
  var chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));
  var emptyBox = document.getElementById('almanac-empty');
  var emptyReset = document.getElementById('empty-reset');

  function applyFilter(season) {
    var shown = 0;

    entries.forEach(function (entry) {
      var match = (season === 'all') || (entry.getAttribute('data-season') === season);
      entry.hidden = !match;
      if (match) { shown += 1; }
    });

    chips.forEach(function (chip) {
      var active = chip.getAttribute('data-filter') === season;
      chip.classList.toggle('is-active', active);
      chip.setAttribute('aria-pressed', active ? 'true' : 'false');
    });

    emptyBox.hidden = shown !== 0;
  }

  chips.forEach(function (chip) {
    chip.addEventListener('click', function () {
      applyFilter(chip.getAttribute('data-filter'));
    });
  });

  emptyReset.addEventListener('click', function () {
    applyFilter('all');
    var anchor = document.querySelector('.entry.is-current .entry__what strong');
    if (anchor) {
      anchor.setAttribute('tabindex', '-1');
      anchor.focus();
    }
  });

  /* ── 03 器物档案原位展开 ─────────────────────── */

  Array.prototype.slice.call(document.querySelectorAll('.card__toggle')).forEach(function (btn) {
    var panel = document.getElementById(btn.getAttribute('aria-controls'));
    var card = btn.closest('.card');
    var label = btn.querySelector('.card__toggle-text');
    if (!panel || !card) { return; }

    btn.addEventListener('click', function () {
      var next = btn.getAttribute('aria-expanded') !== 'true';

      btn.setAttribute('aria-expanded', next ? 'true' : 'false');
      card.classList.toggle('is-open', next);
      panel.hidden = !next;

      if (label) { label.textContent = next ? '收起采集档案' : '展开采集档案'; }

      if (next && !reduce) {
        panel.classList.remove('is-entering');
        void panel.offsetWidth;   /* 强制回流，保证连续展开也能重播动画 */
        panel.classList.add('is-entering');
      }
    });
  });

  /* ── 04 季候信订阅 ───────────────────────────── */

  var form = document.getElementById('signup');
  var input = document.getElementById('email');
  var submit = document.getElementById('signup-submit');
  var submitLabel = submit.querySelector('.btn__label');
  var error = document.getElementById('email-error');
  var done = document.getElementById('signup-done');
  var doneEcho = document.getElementById('signup-email-echo');
  var resetBtn = document.getElementById('signup-reset');
  var row = form.querySelector('.signup__row');

  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  var ASSUMED = 'name@example.com';

  function clearError() {
    error.hidden = true;
    error.textContent = '';
    input.setAttribute('aria-invalid', 'false');
  }

  function showError(message) {
    error.innerHTML = message;
    error.hidden = false;
    input.setAttribute('aria-invalid', 'true');
    input.focus();
  }

  input.addEventListener('input', function () {
    if (input.getAttribute('aria-invalid') === 'true') { clearError(); }
  });

  submit.addEventListener('click', function (event) {
    event.preventDefault();

    var value = input.value.trim();

    if (value === '') {
      showError('还没有填邮箱。写下你的常用邮箱，换季时就能收到这封信。');
      return;
    }

    if (!EMAIL_RE.test(value)) {
      showError('这个邮箱看起来少了点什么。请检查是否有「@」和完整的域名，例如 <a href="#" data-fill="' + ASSUMED + '">' + ASSUMED + '</a>。');
      return;
    }

    clearError();
    submit.disabled = true;
    submitLabel.textContent = '正在记下…';

    /* 本样板没有后端，这里只演示前端状态流转 */
    window.setTimeout(function () {
      submit.disabled = false;
      submitLabel.textContent = '订阅季候信';
      input.value = '';
      row.hidden = true;
      doneEcho.textContent = value;
      done.hidden = false;
      resetBtn.focus();
    }, reduce ? 0 : 520);
  });

  /* 错误提示中的示例邮箱可一键填入 */
  error.addEventListener('click', function (event) {
    var target = event.target;
    if (target && target.getAttribute && target.getAttribute('data-fill')) {
      event.preventDefault();
      input.value = target.getAttribute('data-fill');
      clearError();
      input.focus();
    }
  });

  resetBtn.addEventListener('click', function () {
    done.hidden = true;
    row.hidden = false;
    input.value = '';
    clearError();
    input.focus();
  });

  /* ── 初始状态 ────────────────────────────────── */
  root.setAttribute('data-moment', 'dawn');
  applyFilter('all');
})();

document.getElementById('email').addEventListener('keydown', function(e) { if (e.key === 'Enter') { e.preventDefault(); document.getElementById('signup-submit').click(); } });
